INSERT INTO test_history (id, test_type, test_id, test_title, score, max_score, band_score, time_spent_seconds, answers_json, created_at, user_id) VALUES (1, 'Reading Academic', 'read-01', 'Academic Reading Practice Test 1', 4, 10, 5.0, 120, '[{"id": "q1", "question": "Smart cities only gather information related to traffic and transportation.", "user_answer": "FALSE", "correct_answer": "FALSE", "is_correct": true, "explanation": "\u0110o\u1ea1n 1 n\u00eau r\u00f5: ''This includes data collected from citizens, devices, buildings... traffic, power plants, utilities, water, waste, crime, schools, hospitals...'', do \u0111\u00f3 kh\u00f4ng ch\u1ec9 thu th\u1eadp th\u00f4ng tin giao th\u00f4ng."}, {"id": "q2", "question": "By 2050, more than two-thirds of the world''s population is expected to reside in cities.", "user_answer": "TRUE", "correct_answer": "TRUE", "is_correct": true, "explanation": "\u0110o\u1ea1n 3 ch\u1ec9 ra: ''by 2050, 68% of the world population is projected to be urban'' (68% t\u01b0\u01a1ng \u0111\u01b0\u01a1ng h\u01a1n 2/3)."}, {"id": "q3", "question": "Singapore''s 3D platform has successfully reduced the cost of electricity by 30%.", "user_answer": "", "correct_answer": "NOT GIVEN", "is_correct": false, "explanation": "\u0110o\u1ea1n 3 nh\u1eafc \u0111\u1ebfn n\u1ec1n t\u1ea3ng ''Virtual Singapore'' d\u00f9ng \u0111\u1ec3 m\u00f4 ph\u1ecfng quy ho\u1ea1ch v\u00e0 ti\u1ec1m n\u0103ng n\u0103ng l\u01b0\u1ee3ng m\u1eb7t tr\u1eddi, nh\u01b0ng b\u00e0i \u0111\u1ecdc KH\u00d4NG \u0111\u1ec1 c\u1eadp li\u1ec7u n\u00f3 c\u00f3 gi\u00fap gi\u1ea3m 30% ti\u1ec1n \u0111i\u1ec7n hay kh\u00f4ng."}, {"id": "q4", "question": "What is the primary concern raised by privacy advocates regarding smart cities?", "user_answer": "The pervasive surveillance of citizens'' daily activities", "correct_answer": "The pervasive surveillance of citizens'' daily activities", "is_correct": true, "explanation": "\u0110o\u1ea1n cu\u1ed1i vi\u1ebft: ''Privacy advocates point out the ubiquitous surveillance required by facial recognition cameras... the line between civic optimization and state surveillance blurs rapidly''."}, {"id": "q5", "question": "Hyper-connected cities are vulnerable because a cyberattack could disable either the traffic system or the ________.", "user_answer": "power grid", "correct_answer": "power grid", "is_correct": true, "explanation": "\u0110o\u1ea1n cu\u1ed1i vi\u1ebft: ''...could cripple traffic networks or the power grid for millions of residents''."}, {"id": "q6", "question": "According to the passage, historically, Western philosophy viewed intuition as:", "user_answer": "", "correct_answer": "An unscientific and inferior form of judgment", "is_correct": false, "explanation": "\u0110o\u1ea1n 1 n\u00eau r\u00f5: ''Gut feelings and intuitive impulses were frequently dismissed as unscientific superstitions''."}, {"id": "q7", "question": "Which of the following best characterizes Kahneman''s ''System 1''?", "user_answer": "", "correct_answer": "Fast, effortless, and associative", "is_correct": false, "explanation": "\u0110o\u1ea1n 2 n\u00eau: ''System 1 operates automatically, swiftly, and with minimal voluntary effort. It is associative, emotionally charged...''"}, {"id": "q8", "question": "Experienced firefighters usually list several strategies and analyze the benefits of each before acting.", "user_answer": "", "correct_answer": "FALSE", "is_correct": false, "explanation": "\u0110o\u1ea1n 3 vi\u1ebft: ''seasoned fire captains rarely compare multiple courses of action. Instead, their subconscious instantly matches current perceptual cues...'' (hi\u1ebfm khi so s\u00e1nh nhi\u1ec1u ph\u01b0\u01a1ng \u00e1n)."}, {"id": "q9", "question": "Gary Klein coined the term ''________'' to describe the rapid matching of cues to past experiences.", "user_answer": "", "correct_answer": "Recognition-Primed Decision", "is_correct": false, "explanation": "\u0110o\u1ea1n 3 vi\u1ebft: ''This process, termed Recognition-Primed Decision (RPD)...''"}, {"id": "q10", "question": "Daniel Kahneman received a Nobel Memorial Prize in Economic Sciences.", "user_answer": "", "correct_answer": "NOT GIVEN", "is_correct": false, "explanation": "M\u1eb7c d\u00f9 ngo\u00e0i \u0111\u1eddi Daniel Kahneman \u0111o\u1ea1t gi\u1ea3i Nobel, nh\u01b0ng trong n\u1ed9i dung b\u00e0i \u0111\u1ecdc tr\u00ean KH\u00d4NG nh\u1eafc t\u1edbi th\u00f4ng tin n\u00e0y."}]', '2026-09-09 02:25:00', NULL) ON CONFLICT DO NOTHING;
