INSERT INTO test_history (id, test_type, test_id, test_title, score, max_score, band_score, time_spent_seconds, answers_json, created_at, user_id) VALUES (4, 'Reading Academic', 'read-01', 'Academic Reading Practice Test 1', 4, 10, 5.0, 120, '[{"id": "q1", "question": "Smart cities only gather information related to traffic and transportation.", "user_answer": "FALSE", "correct_answer": "FALSE", "is_correct": true, "explanation": "\u0110o\u1ea1n 1 n\u00eau r\u00f5: ''This includes data collected from citizens, devices, buildings... traffic, power plants, utilities, water, waste, crime, schools, hospitals...'', do \u0111\u00f3 kh\u00f4ng ch\u1ec9 thu th\u1eadp th\u00f4ng tin giao th\u00f4ng."}, {"id": "q2", "question": "By 2050, more than two-thirds of the world''s population is expected to reside in cities.", "user_answer": "TRUE", "correct_answer": "TRUE", "is_correct": true, "explanation": "\u0110o\u1ea1n 3 ch\u1ec9 ra: ''by 2050, 68% of the world population is projected to be urban'' (68% t\u01b0\u01a1ng \u0111\u01b0\u01a1ng h\u01a1n 2/3)."}, {"id": "q3", "question": "Singapore''s 3D platform has successfully reduced the cost of electricity by 30%.", "user_answer": "", "correct_answer": "NOT GIVEN", "is_correct": false, "explanation": "\u0110o\u1ea1n 3 nh\u1eafc \u0111\u1ebfn n\u1ec1n t\u1ea3ng ''Virtual Singapore'' d\u00f9ng \u0111\u1ec3 m\u00f4 ph\u1ecfng quy ho\u1ea1ch v\u00e0 ti\u1ec1m n\u0103ng n\u0103ng l\u01b0\u1ee3ng m\u1eb7t tr\u1eddi, nh\u01b0ng b\u00e0i \u0111\u1ecdc KH\u00d4NG \u0111\u1ec1 c\u1eadp li\u1ec7u n\u00f3 c\u00f3 gi\u00fap gi\u1ea3m 30% ti\u1ec1n \u0111i\u1ec7n hay kh\u00f4ng."}, {"id": "q4", "question": "What is the primary concern raised by privacy advocates regarding smart cities?", "user_answer": "The pervasive surveillance of citizens'' daily activities", "correct_answer": "The pervasive surveillance of citizens'' daily activities", "is_correct": true, "explanation": "\u0110o\u1ea1n cu\u1ed1i vi\u1ebft: ''Privacy advocates point out th