INSERT INTO writing_submissions (id, task_type, prompt_id, prompt_title, essay_text, word_count, estimated_band, evaluation_json, created_at, user_id) VALUES (1, 'task2', 'write-t2-01', 'AI and Teachers', 'In recent decades, environmental degradation has emerged as an unprecedented global crisis. Governments must enforce stringent environmental policies to mitigate carbon emissions. Furthermore, individual citizens also bear significant responsibility for conservation. In conclusion, collaborative efforts are paramount to sustainable progress.', 40, 5.6, '{"task_response": {"score": 4.0, "comments": ["B\u00e0i vi\u1ebft ch\u01b0a \u0111\u1ea1t \u0111\u1ed9 d\u00e0i t\u1ed1i thi\u1ec3u 250 t\u1eeb (hi\u1ec7n t\u1ea1i: 40 t\u1eeb), s\u1ebd b\u1ecb tr\u1eeb \u0111i\u1ec3m Task Response.", "C\u1ea7n ph\u00e2n chia \u0111o\u1ea1n v\u0103n r\u00f5 r\u00e0ng (M\u1edf b\u00e0i, Th\u00e2n b\u00e0i 1, Th\u00e2n b\u00e0i 2, K\u1ebft lu\u1eadn)."]}, "coherence_cohesion": {"score": 5.5, "comments": ["N\u00ean b\u1ed5 sung th\u00eam c\u00e1c li\u00ean t\u1eeb h\u1ecdc thu\u1eadt (Furthermore, In contrast, Consequently, Overall...)."]}, "lexical_resource": {"score": 7.0, "comments": ["V\u1ed1n t\u1eeb t\u1ed1t, c\u00f3 s\u1eed d\u1ee5ng 5 t\u1eeb v\u1ef1ng h\u1ecdc thu\u1eadt."], "detected_academic": ["unprecedented", "mitigate", "paramount", "stringent", "significant"]}, "grammatical_accuracy": {"score": 6.0, "comments": ["N\u00ean \u0111a d\u1ea1ng h\u00f3a c\u1ea5u tr\u00fac c\u00e2u: c\u00e2u gh\u00e9p, m\u1ec7nh \u0111\u1ec1 quan h\u1ec7, c\u00e2u \u0111i\u1ec1u ki\u1ec7n, c\u1ea5u tr\u00fac b\u1ecb \u0111\u1ed9ng."]}, "overall_band": 5.6, "word_count": 40, "paragraph_count": 1}', '2026-09-09 02:25:01', NULL) ON CONFLICT DO NOTHING;
