INSERT INTO writing_submissions (id, task_type, prompt_id, prompt_title, essay_text, word_count, estimated_band, evaluation_json, created_at, user_id) VALUES (3, 'task1', 'write-t1-01', 'Renewable Energy Consumption in 4 Nations (2005 - 2025)', 'The line graph illustrates the proportion of renewable energy in the overall power production of four nations—Germany, Sweden, the United Kingdom, and Australia—from 2005 to 2025, with forecasted figures extending to 2030. Overall, all four countries witnessed an upward trajectory in their reliance on renewable energy, with Sweden consistently dominating the group throughout the given timeframe. Furthermore, while the UK exhibited the most dramatic acceleration, Australia experienced comparatively sluggish progress. In 2005, Sweden commenced with the highest share at approximately 38%, before rising steadily to exceed 55% by 2025 and is anticipated to reach an unprecedented peak of 62% by 2030. In contrast, the United Kingdom started from a modest baseline of merely 5% in 2005. However, following substantial investments after 2012, its green energy percentage climbed steeply, surpassing Germany around 2022 to record 44% in 2025, and is expected to hit 50% by 2030. Meanwhile, Germany saw a consistent and substantial increase from 12% in 2005 to 40% in 2025. Conversely, Australia showed the least pronounced growth, hovering between 7% and 15% across the twenty-year period, with projections suggesting a marginal rise to just under 18% by the decade''s end.', 195, 6.6, '{"task_response": {"score": 7.0, "comments": ["\u0110\u1ed9 d\u00e0i t\u1ed1t (195 t\u1eeb), \u0111\u00e1p \u1ee9ng ti\u00eau chu\u1ea9n ph\u00f2ng thi.", "C\u1ea7n ph\u00e2n chia \u0111o\u1ea1n v\u0103n r\u00f5 r\u00e0ng (M\u1edf b\u00e0i, Th\u00e2n b\u00e0i 1, Th\u00e2n b\u00e0i 2, K\u1ebft lu\u1eadn)."]}, "coherence_cohesion": {"score": 6.5, "comments": ["C\u00f3 s\u1eed d\u1ee5ng t\u1eeb n\u1ed1i (4 t\u1eeb n\u1ed1i), li\u00ean k\u1ebft \u00fd t\u01b0\u01a1ng \u0111\u1ed1i m\u01b0\u1ee3t."]}, "lexical_resource": {"score": 7.0, "comments": ["V\u1ed1n t\u1eeb t\u1ed1t, c\u00f3 s\u1eed d\u1ee5ng 3 t\u1eeb v\u1ef1ng h\u1ecdc thu\u1eadt."], "detected_academic": ["unprecedented", "trajectory", "substantial"]}, "grammatical_accuracy": {"score": 6.0, "comments": ["N\u00ean \u0111a d\u1ea1ng h\u00f3a c\u1ea5u tr\u00fac c\u00e2u: c\u00e2u gh\u00e9p, m\u1ec7nh \u0111\u1ec1 quan h\u1ec7, c\u00e2u \u0111i\u1ec1u ki\u1ec7n, c\u1ea5u tr\u00fac b\u1ecb \u0111\u1ed9ng."]}, "overall_band": 6.6, "word_count": 195, "paragraph_count": 1}', '2026-09-09 02:35:30', NULL) ON CONFLICT DO NOTHING;
