INSERT INTO cached_vocabulary (word, phonetic, audio, pos, definition_en, example_en, meaning_vi, ielts_explanation, ielts_example, collocations_json, synonyms_json, antonyms_json, band, topic, source, created_at, updated_at) VALUES ('deserve', '/deserve/', 'https://api.dictionaryapi.dev/media/pronunciations/en/deserve-us.mp3', 'noun', 'To perform or embody the academic quality of deserve.', 'In academic discourse, researchers frequently examine deserve as a key variable.', 'Xứng đáng, đáng được hưởng', 'Động từ biểu đạt sự xứng đáng, thường dùng trong IELTS Writing Task 2 khi lập luận về quyền lợi của người lao động, chính sách xã hội hoặc sự công nhận đối với các đóng góp công cộng.', 'Dedicated educators and healthcare professionals richly deserve higher remuneration and greater societal recognition for their essential contributions.', '["richly deserve", "deserve consideration", "well deserve", "deserve priority"]', '[]', '[]', 'Band 7.0+', 'Society & Ethics', 'academic_synthesis', '2026-09-09 03:35:53', '2026-09-09 03:35:53') ON CONFLICT DO NOTHING;
INSERT INTO cached_vocabulary (word, phonetic, audio, pos, definition_en, example_en, meaning_vi, ielts_explanation, ielts_example, collocations_json, synonyms_json, antonyms_json, band, topic, source, created_at, updated_at) VALUES ('mitigate', '/ˈmɪt.ɪ.ɡeɪt/', 'https://api.dictionaryapi.dev/media/pronunciations/en/mitigate-us.mp3', 'verb', 'Core academic vocabulary for Environment & Climate Change.', 'Governments must enforce stringent environmental policies to mitigate the severe consequences of global warming.', 'Làm giảm thiểu, xoa dịu tác hại', 'Từ vựng học thuật trọng tâm trong chủ đề Environment & Climate Change. Tối ưu hóa điểm số Lexical Resource.', 'Governments must enforce stringent environmental policies to mitigate the severe consequences of global warming.', '["mitigate the impact", "mitigate risks", "mitigate climate change"]', '["alleviate", "attenuate", "lessen"]', '[]', '7.5+', 'Environment & Climate Change', 'curated_ielts_dataset', '2026-09-09 03:44:38', '2026-09-09 03:44:38') ON CONFLICT DO NOTHING;
INSERT INTO cached_vocabulary (word, phonetic, audio, pos, definition_en, example_en, meaning_vi, ielts_explanation, ielts_example, collocations_json, synonyms_json, antonyms_json, band, topic, source, created_at, updated_at) VALUES ('biodiversity', '/ˌbaɪ.oʊ.daɪˈvɜːr.sə.t̬i/', 'https://api.dictionaryapi.dev/media/pronunciations/en/biodiversity-us.mp3', 'noun', 'Core academic vocabulary for Environment & Climate Change.', 'Deforestation in tropical rainforests poses an imminent existential threat to global terrestrial biodiversity.', 'Đa dạng sinh học', 'Từ vựng học thuật trọng tâm trong chủ đề Environment & Climate Change. Tối ưu hóa điểm số Lexical Resource.', 'Deforestation in tropical rainforests poses an imminent existential threat to global terrestrial biodiversity.', '["preserve biodiversity", "loss of biodiversity", "threaten biodiversity"]', '["ecological variety", "species richness"]', '[]', '7.5+', 'Environment & Climate Change', 'curated_ielts_dataset', '2026-09-09 03:44:38', '2026-09-09 03:44:38') ON CONFLICT DO NOTHING;
